$(document).ready((function(){$(".page-preview").click((function(e){e.stopImmediatePropagation()})),$(".std-nav-tree label").click((function(e){var t=$(this);t.next("ul").length&&(e.preventDefault(),t.next("ul").slideToggle("fast",(function(){$(this).parent("li").toggleClass("expanded"),$(this).removeAttr("style")})))})),$(".std-nav-tree label > input.checkpage").click((function(e){e.stopPropagation()})),$(".std-nav-tree-expand-all").click((function(e){var t;e.preventDefault(),$(this).closest(".tree-selector").siblings(".std-nav-tree").find("li").removeClass("expanded").addClass("expanded")})),$(".std-nav-tree-collapse-all").click((function(e){var t;e.preventDefault(),$(this).closest(".tree-selector").siblings(".std-nav-tree").find("li").removeClass("expanded")})),$(".std-nav-tree-select-all").click((function(e){e.preventDefault(),$(".std-nav-tree .checkpage").prop("checked",!0),$(".std-nav-tree-expand-all").trigger("click")})),$(".std-nav-tree-select-none").click((function(e){e.preventDefault(),$(".std-nav-tree .checkpage").prop("checked",!1),$(".std-nav-tree-collapse-all").trigger("click")}))}));